template:
@php
    // The switch says where the video is; a block saved before it had a value is a link, as new ones are.
    $fromFile = $source === 'file';
    $address = ! $fromFile && is_string($link) ? trim($link) : '';
    // An address of no provider the site knows is not printed: the component would refuse it, and the page with it.
    $known = $address !== '' && app(\WebxUi\Widgets\Video\VideoProviders::class)->find($address) !== null;
    // A video or a picture deleted from the library resolves without an address: as if never picked.
    $clip = $fromFile && is_array($file) && ! empty($file['url']) ? $file : null;
    $picture = is_array($poster) && ! empty($poster['url']) ? $poster : null;
    $shape = in_array($ratio, ['16/9', '4/3', '1/1', '9/16'], true) ? $ratio : '16/9';
    $title = $heading ? wx_text($heading)->plain() : null;
@endphp
@if ($clip || $known)
<section class="b-video b-video--{{ str_replace('/', '-', $shape) }}" data-wx-block="video">
    @if ($heading)
        <h2 class="b-video__heading">{{ $heading }}</h2>
    @endif
    <figure class="b-video__figure">
        @if ($clip)
            <x-webx-video :file="$clip" :poster="$picture" :title="$title" :ratio="$shape" />
        @else
            <x-webx-video :src="$address" :poster="$picture" :title="$title" :ratio="$shape" />
        @endif
        @if ($caption)
            <figcaption class="b-video__caption">{{ $caption }}</figcaption>
        @endif
    </figure>
</section>
@endif

styles:
.b-video {
    container-type: inline-size;
}

.b-video__heading {
    margin: 0 0 1em;
}

/* No margin of its own: a theme's prose spaces figures, and the frame keeps to the column. */
.b-video__figure {
    margin: 0 auto;
}

/* A square or an upright video as wide as the column would be taller than any screen: held to a
   width a phone's video would have, in the middle. */
.b-video--1-1 .b-video__figure {
    max-width: 36em;
}

.b-video--9-16 .b-video__figure {
    max-width: 22em;
}

.b-video__caption {
    margin: 0.5em 0 0;
    font-size: 0.875em;
    opacity: 0.75;
}
